 private void LoadInstance(){if(CurrentInstance is not{}i)return;_instanceName.Text=i.Name;_sourceType.SelectedItem=i.SourceType;_source.Text=i.Source;_rate.SelectedItem=i.InputSampleRate;_encodersList.ItemsSource=i.Encoders;_encodersList.SelectedIndex=i.Encoders.Count>0?0:-1;}private void LoadEncoder(){if(CurrentEncoder is not{}e)return;_encoderName.Text=e.Name;_codec.SelectedItem=e.Codec;_outputMode.SelectedItem=e.OutputMode;_bitrate.SelectedItem=e.BitrateKbps;_sampleRate.SelectedItem=e.SampleRate;_channel.SelectedItem=e.ChannelMode;_server.SelectedItem=e.ServerType;_host.Text=e.Host;_port.Text=e.Port.ToString();_mount.Text=e.Mount;_password.Text=e.Password;_metadata.Text=e.Metadata;_stationName.Text=e.StationName;_description.Text=e.Description;_stationUrl.Text=e.StationUrl;_genre.Text=e.Genre;_log.Text=e.Log;}
